    Currency currency0;
    /// @notice The higher currency of the pool, sorted numerically
    Currency currency1;
    /// @notice The pool LP fee, capped at 1_000_000. If the highest bit is 1, the pool has a dynamic fee and must be exactly equal to 0x800000
    uint24 fee;
    /// @notice Ticks that involve positions must be a multiple of tick spacing
    int24 tickSpacing;
    /// @notice The hooks of the pool
    IHooks hooks;
}

script/DeployCtrlArc.s.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {Script} from "forge-std/Script.sol";
import {console2} from "forge-std/console2.sol";
import {CtrlFeeVault} from "../src/CtrlFeeVault.sol";
import {CtrlNativeLaunchHook} from "../src/CtrlNativeLaunchHook.sol";
import {CtrlLaunchRouter} from "../src/CtrlLaunchRouter.sol";
import {CtrlPositionLocker} from "../src/CtrlPositionLocker.sol";
import {CtrlReferralRegistry} from "../src/CtrlReferralRegistry.sol";
import {CtrlNativeV4Factory} from "../src/CtrlNativeV4Factory.sol";

contract CtrlNativeHookCreate2Deployer {
    error DeploymentFailed();

    function deploy(bytes32 salt, bytes memory creationCode) external returns (address deployed) {
        assembly ("memory-safe") {
            deployed := create2(0, add(creationCode, 0x20), mload(creationCode), salt)
        }
        if (deployed == address(0)) revert DeploymentFailed();
    }
}

/// @notice Deploys a new immutable Ctrl launch stack; existing V2 pools are unaffected.
/// @dev CtrlNativeLaunchHook is deployed directly with CREATE2, without a proxy or upgrade authority.
contract DeployCtrlArc is Script {
    uint160 private constant ALL_HOOK_MASK = (1 << 14) - 1;
    uint160 private constant CTRL_HOOK_FLAGS = 0x28cc;

    address private constant ARC_POOL_MANAGER = 0x8366a39CC670B4001A1121B8F6A443A643e40951;
    address private constant ARC_POSITION_MANAGER = 0x6049c9a0e26405C0985f9E3685C87d0aE917f82B;
    address private constant PERMIT2 = 0x000000000022D473030F116dDEE9F6B43aC78BA3;

    struct Deployment {
        CtrlFeeVault vault;
        CtrlReferralRegistry registry;
        CtrlPositionLocker locker;
        CtrlNativeLaunchHook hook;
        CtrlLaunchRouter router;
        CtrlNativeV4Factory factory;
        CtrlNativeHookCreate2Deployer hookDeployer;
    }

    struct Config {
        uint256 privateKey;
        address owner;
        address treasury;
        uint256 expectedChainId;
        uint256 launchFee;
        uint256 graduationThreshold;
        int24 initialTick;
        address poolManager;
        address positionManager;
        address permit2;
        bytes32 poolManagerCodehash;
        bytes32 positionManagerCodehash;
        bytes32 permit2Codehash;
    }

    function run() external returns (Deployment memory) {
        return _deploy(
            Config({
                privateKey: vm.envUint("PRIVATE_KEY"),
                owner: vm.envAddress("OWNER"),
                treasury: vm.envAddress("TREASURY"),
                expectedChainId: 5042,
                launchFee: vm.envUint("ARC_LAUNCH_FEE_WEI"),
                graduationThreshold: vm.envUint("ARC_GRADUATION_THRESHOLD_WEI"),
                initialTick: _configuredTick(),
                poolManager: vm.envOr("POOL_MANAGER", ARC_POOL_MANAGER),
                positionManager: vm.envOr("POSITION_MANAGER", ARC_POSITION_MANAGER),
                permit2: vm.envOr("PERMIT2", PERMIT2),
                poolManagerCodehash: vm.envBytes32("POOL_MANAGER_CODEHASH"),
                positionManagerCodehash: vm.envBytes32("POSITION_MANAGER_CODEHASH"),
                permit2Codehash: vm.envBytes32("PERMIT2_CODEHASH")
            })
        );
    }

    function _deploy(Config memory config) internal returns (Deployment memory deployment) {
        require(block.chainid == config.expectedChainId, "unexpected chain id");
        require(config.owner != address(0), "OWNER is zero");
        require(config.treasury != address(0), "TREASURY is zero");
        _requireCodeHash(config.poolManager, config.poolManagerCodehash);
        _requireCodeHash(config.positionManager, config.positionManagerCodehash);
        _requireCodeHash(config.permit2, config.permit2Codehash);

        address broadcaster = vm.addr(config.privateKey);
        vm.startBroadcast(config.privateKey);
        deployment.vault = new CtrlFeeVault(config.owner, config.poolManager, config.treasury, broadcaster);
        deployment.registry = new CtrlReferralRegistry();
        deployment.locker = new CtrlPositionLocker(config.positionManager, broadcaster);
        deployment.hookDeployer = new CtrlNativeHookCreate2Deployer();

        bytes memory hookCreationCode = abi.encodePacked(
            type(CtrlNativeLaunchHook).creationCode,
            abi.encode(
                config.poolManager,
                config.positionManager,
                address(deployment.vault),
                address(deployment.registry),
                broadcaster,
                config.graduationThreshold,
                config.initialTick
            )
        );
        bytes32 hookSalt = _mineHookSalt(address(deployment.hookDeployer), keccak256(hookCreationCode));
        deployment.hook = CtrlNativeLaunchHook(deployment.hookDeployer.deploy(hookSalt, hookCreationCode));
        deployment.router = new CtrlLaunchRouter(config.poolManager, address(deployment.hook));
        deployment.factory = new CtrlNativeV4Factory(
            config.owner,
            config.poolManager,
            config.positionManager,
            config.permit2,
            address(deployment.locker),
            address(deployment.hook),
            address(deployment.router),
            address(deployment.vault),
            config.launchFee,
            config.initialTick
        );

        deployment.hook.initializeFactory(address(deployment.factory));
        deployment.vault.initializeHook(address(deployment.hook));
        deployment.locker.initializeFactory(address(deployment.factory));
        vm.stopBroadcast();

        require(deployment.factory.launchesArePaused(), "factory unexpectedly open");
        require(uint160(address(deployment.hook)) & ALL_HOOK_MASK == CTRL_HOOK_FLAGS, "invalid hook permissions");
        require(deployment.hook.factory() == address(deployment.factory), "hook factory mismatch");
        require(deployment.vault.hook() == address(deployment.hook), "vault hook mismatch");
        require(deployment.locker.factory() == address(deployment.factory), "locker factory mismatch");

        console2.log("CtrlNativeV4Factory", address(deployment.factory));
        console2.log("CtrlNativeLaunchHook", address(deployment.hook));
        console2.log("CtrlLaunchRouter", address(deployment.router));
        console2.log("CtrlFeeVault", address(deployment.vault));
        console2.log("CtrlReferralRegistry", address(deployment.registry));
        console2.log("CtrlPositionLocker", address(deployment.locker));
        console2.log("CtrlNativeHookCreate2Deployer", address(deployment.hookDeployer));
        console2.log("Hook runtime code hash");
        console2.logBytes32(address(deployment.hook).codehash);
        console2.log("Hook CREATE2 salt");
        console2.logBytes32(hookSalt);
    }

    function _mineHookSalt(address deployer, bytes32 initCodeHash) private pure returns (bytes32 salt) {
        for (uint256 i; i < 1_000_000; ++i) {
            salt = bytes32(i);
            address predicted =
                address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xff), deployer, salt, initCodeHash)))));
            if (uint160(predicted) & ALL_HOOK_MASK == CTRL_HOOK_FLAGS) return salt;
        }
        revert("hook salt not found");
    }

    function _configuredTick() private view returns (int24) {
        int256 tick = vm.envInt("ARC_INITIAL_TICK");
        require(tick > -887_200 && tick <= 887_200 && tick % 200 == 0, "invalid configured tick");
        return int24(tick);
    }

    function _requireCodeHash(address target, bytes32 expectedCodehash) private view {
        require(expectedCodehash != bytes32(0), "expected codehash is zero");
        require(target.code.length != 0, "dependency has no code");
        require(target.codehash == expectedCodehash, "dependency codehash mismatch");
    }
}

src/CtrlFeeVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IPoolManager} from "@uniswap/v4-core/src/interfaces/IPoolManager.sol";
import {IUnlockCallback} from "@uniswap/v4-core/src/interfaces/callback/IUnlockCallback.sol";
import {Currency, CurrencyLibrary} from "@uniswap/v4-core/src/types/Currency.sol";
import {ICtrlFeeVault} from "./interfaces/ICtrlProtocol.sol";

/// @notice Pull-based accounting vault backed by PoolManager native-ETH ERC-6909 claims.
contract CtrlFeeVault is Ownable2Step, ReentrancyGuard, IUnlockCallback, ICtrlFeeVault {
    using CurrencyLibrary for Currency;

    struct ClaimCallback {
        address payable recipient;
        uint256 amount;
    }

    error AlreadyInitialized();
    error Insolvent();
    error InvalidAccrual();
    error NoFees();
    error NotHook();
    error NotInitializer();
    error NotPoolManager();
    error ReservedBountyExceeded();
    error ZeroAddress();

    event HookInitialized(address indexed hook);
    event FeeAllocationAccrued(
        address indexed token,
        address indexed creatorPayout,
        uint256 creatorAmount,
        address indexed referralPayout,
        uint256 referralAmount,
        address treasury,
        uint256 protocolAmount,
        uint256 bountyAmount
    );
    event BountyReleased(address indexed token, address indexed recipient, uint256 amount);
    event CreatorFeesClaimed(address indexed token, address indexed recipient, uint256 amount);
    event ReferralFeesClaimed(address indexed recipient, uint256 amount);
    event ProtocolFeesClaimed(address indexed recipient, uint256 amount);
    event GraduationBountyClaimed(address indexed recipient, uint256 amount);
    event TreasuryUpdated(address indexed previousTreasury, address indexed newTreasury);

    IPoolManager public immutable poolManager;
    address public immutable initializer;
    address public hook;
    address public override treasury;

    mapping(address token => mapping(address recipient => uint256 amount)) public creatorClaimableEth;
    mapping(address recipient => uint256 amount) public referralClaimableEth;
    mapping(address recipient => uint256 amount) public protocolClaimableEth;
    mapping(address recipient => uint256 amount) public bountyClaimableEth;
    mapping(address token => uint256 amount) public reservedBountyEthForToken;
    uint256 public totalClaimableEth;
    uint256 public reservedBountyEth;
    uint256 public totalLiabilityEth;

    constructor(address initialOwner, address poolManager_, address treasury_, address initializer_)
        Ownable(initialOwner)
    {
        if (
            initialOwner == address(0) || poolManager_ == address(0) || treasury_ == address(0)
                || initializer_ == address(0)
        ) {
            revert ZeroAddress();
        }
        poolManager = IPoolManager(poolManager_);
        treasury = treasury_;
        initializer = initializer_;
    }

    modifier onlyHook() {
        if (msg.sender != hook) revert NotHook();
        _;
    }

    function initializeHook(address hook_) external {
        if (msg.sender != initializer) revert NotInitializer();
        if (hook != address(0)) revert AlreadyInitialized();
        if (hook_ == address(0)) revert ZeroAddress();
        hook = hook_;
        emit HookInitialized(hook_);
    }

    function accrue(
        address token,
        address creatorPayout,
        uint256 creatorAmount,
        address referralPayout,
        uint256 referralAmount,
        uint256 protocolAmount,
        uint256 bountyAmount
    ) external onlyHook {
        if (token == address(0) || creatorPayout == address(0)) revert InvalidAccrual();
        if (referralAmount != 0 && referralPayout == address(0)) revert InvalidAccrual();

        uint256 claimableIncrease = creatorAmount + referralAmount + protocolAmount;
        uint256 liabilityIncrease = claimableIncrease + bountyAmount;

        creatorClaimableEth[token][creatorPayout] += creatorAmount;
        if (referralAmount != 0) referralClaimableEth[referralPayout] += referralAmount;
        protocolClaimableEth[treasury] += protocolAmount;
        totalClaimableEth += claimableIncrease;
        reservedBountyEthForToken[token] += bountyAmount;
        reservedBountyEth += bountyAmount;
        totalLiabilityEth += liabilityIncrease;

        if (poolManager.balanceOf(address(this), 0) < totalLiabilityEth) revert Insolvent();
        emit FeeAllocationAccrued(
            token, creatorPayout, creatorAmount, referralPayout, referralAmount, treasury, protocolAmount, bountyAmount
        );
    }

    function releaseBounty(address token, address recipient, uint256 amount) external onlyHook {
        if (token == address(0) || recipient == address(0)) revert ZeroAddress();
        if (amount > reservedBountyEthForToken[token]) revert ReservedBountyExceeded();

        reservedBountyEthForToken[token] -= amount;
        reservedBountyEth -= amount;
        bountyClaimableEth[recipient] += amount;
        totalClaimableEth += amount;
        emit BountyReleased(token, recipient, amount);
    }

    function claimCreator(address token) external nonReentrant returns (uint256 amount) {
        amount = creatorClaimableEth[token][msg.sender];
        if (amount == 0) revert NoFees();
        creatorClaimableEth[token][msg.sender] = 0;
        _pay(payable(msg.sender), amount);
        emit CreatorFeesClaimed(token, msg.sender, amount);
    }

    function claimReferral() external nonReentrant returns (uint256 amount) {
        amount = referralClaimableEth[msg.sender];
        if (amount == 0) revert NoFees();
        referralClaimableEth[msg.sender] = 0;
        _pay(payable(msg.sender), amount);
        emit ReferralFeesClaimed(msg.sender, amount);
    }

    function claimProtocol() external nonReentrant returns (uint256 amount) {
        amount = protocolClaimableEth[msg.sender];
        if (amount == 0) revert NoFees();
        protocolClaimableEth[msg.sender] = 0;
        _pay(payable(msg.sender), amount);
        emit ProtocolFeesClaimed(msg.sender, amount);
    }

    function claimGraduationBounty() external nonReentrant returns (uint256 amount) {
        amount = bountyClaimableEth[msg.sender];
        if (amount == 0) revert NoFees();
        bountyClaimableEth[msg.sender] = 0;
        _pay(payable(msg.sender), amount);
        emit GraduationBountyClaimed(msg.sender, amount);
    }

    function unlockCallback(bytes calldata data) external returns (bytes memory) {
        if (msg.sender != address(poolManager)) revert NotPoolManager();
        ClaimCallback memory callback = abi.decode(data, (ClaimCallback));

        poolManager.burn(address(this), 0, callback.amount);
        poolManager.take(CurrencyLibrary.ADDRESS_ZERO, callback.recipient, callback.amount);
        return bytes("");
    }

    function setTreasury(address newTreasury) external onlyOwner {
        if (newTreasury == address(0)) revert ZeroAddress();
        address previousTreasury = treasury;
        treasury = newTreasury;
        emit TreasuryUpdated(previousTreasury, newTreasury);
    }

    function isSolvent() external view returns (bool) {
        return poolManager.balanceOf(address(this), 0) >= totalLiabilityEth;
    }

    function _pay(address payable recipient, uint256 amount) private {
        totalClaimableEth -= amount;
        totalLiabilityEth -= amount;
        poolManager.unlock(abi.encode(ClaimCallback({recipient: recipient, amount: amount})));
    }
}

