// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IPoolManager} from "@uniswap/v4-core/src/interfaces/IPoolManager.sol";
import {IUnlockCallback} from "@uniswap/v4-core/src/interfaces/callback/IUnlockCallback.sol";
import {SafeCast} from "@uniswap/v4-core/src/libraries/SafeCast.sol";
import {TickMath} from "@uniswap/v4-core/src/libraries/TickMath.sol";
import {BalanceDelta, BalanceDeltaLibrary} from "@uniswap/v4-core/src/types/BalanceDelta.sol";
import {Currency, CurrencyLibrary} from "@uniswap/v4-core/src/types/Currency.sol";
import {PoolKey} from "@uniswap/v4-core/src/types/PoolKey.sol";
import {CtrlLaunchHookV1} from "./CtrlLaunchHookV1.sol";

/// @notice Adminless exact-input ETH adapter for Ctrl pools.
/// @dev Universal Router and other V4 routers may be used directly; this router provides
///      predictable full-fill and attribution semantics for Ctrl-native flows.
contract CtrlLaunchRouter is IUnlockCallback, ReentrancyGuard {
    using BalanceDeltaLibrary for BalanceDelta;
    using CurrencyLibrary for Currency;
    using SafeCast for uint256;
    using SafeERC20 for IERC20;

    enum Action {
        BuyExactIn,
        SellExactIn
    }

    struct CallbackData {
        Action action;
        address token;
        address recipient;
        uint256 amountIn;
        uint256 amountOutMinimum;
        bytes hookData;
    }

    error DeadlineExpired();
    error InvalidEthSender();
    error InvalidRecipient();
    error NotPoolManager();
    error PartialFill();
    error SlippageExceeded(uint256 amountOut, uint256 minimum);
    error SlippageRequired();
    error ZeroAddress();
    error ZeroAmount();

    event Bought(
        address indexed payer,
        address indexed recipient,
        address indexed token,
        uint256 ethIn,
        uint256 tokensOut,
        address beneficiary,
        address referrer
    );
    event Sold(
        address indexed payer,
        address indexed recipient,
        address indexed token,
        uint256 tokensIn,
        uint256 ethOut,
        address beneficiary,
        address referrer
    );

    IPoolManager public immutable poolManager;
    CtrlLaunchHookV1 public immutable hook;

    constructor(address poolManager_, address hook_) {
        if (poolManager_ == address(0) || hook_ == address(0)) revert ZeroAddress();
        poolManager = IPoolManager(poolManager_);
        hook = CtrlLaunchHookV1(hook_);
    }

    function buyExactIn(
        address token,
        address recipient,
        address beneficiary,
        address referrer,
        uint256 amountOutMinimum,
        uint256 deadline
    ) external payable nonReentrant returns (uint256 amountOut) {
        if (token == address(0)) revert ZeroAddress();
        if (msg.value == 0) revert ZeroAmount();
        if (amountOutMinimum == 0) revert SlippageRequired();
        if (deadline < block.timestamp) revert DeadlineExpired();
        if (recipient == address(0)) recipient = msg.sender;
        if (recipient == address(this)) revert InvalidRecipient();
        if (beneficiary == address(0)) beneficiary = msg.sender;

        amountOut = abi.decode(
            poolManager.unlock(
                abi.encode(
                    CallbackData({
                        action: Action.BuyExactIn,
                        token: token,
                        recipient: recipient,
                        amountIn: msg.value,
                        amountOutMinimum: amountOutMinimum,
                        hookData: abi.encode(beneficiary, referrer)
                    })
                )
            ),
            (uint256)
        );
        emit Bought(msg.sender, recipient, token, msg.value, amountOut, beneficiary, referrer);
    }

    function sellExactIn(
        address token,
        uint256 amountIn,
        address recipient,
        address beneficiary,
        address referrer,
        uint256 amountOutMinimum,
        uint256 deadline
    ) external nonReentrant returns (uint256 amountOut) {
        if (token == address(0)) revert ZeroAddress();
        if (amountIn == 0) revert ZeroAmount();
        if (amountOutMinimum == 0) revert SlippageRequired();
        if (deadline < block.timestamp) revert DeadlineExpired();
        if (recipient == address(0)) recipient = msg.sender;
        if (recipient == address(this)) revert InvalidRecipient();
        if (beneficiary == address(0)) beneficiary = msg.sender;

        IERC20(token).safeTransferFrom(msg.sender, address(this), amountIn);
        amountOut = abi.decode(
            poolManager.unlock(
                abi.encode(
                    CallbackData({
                        action: Action.SellExactIn,
                        token: token,
                        recipient: recipient,
                        amountIn: amountIn,
                        amountOutMinimum: amountOutMinimum,
                        hookData: abi.encode(beneficiary, referrer)
                    })
                )
            ),
            (uint256)
        );
        emit Sold(msg.sender, recipient, token, amountIn, amountOut, beneficiary, referrer);
    }

    function unlockCallback(bytes calldata data) external returns (bytes memory) {
        if (msg.sender != address(poolManager)) revert NotPoolManager();
        CallbackData memory callback = abi.decode(data, (CallbackData));
        PoolKey memory key = hook.poolKey(callback.token);

        if (callback.action == Action.BuyExactIn) {
            return abi.encode(_buy(key, callback));
        }
        return abi.encode(_sell(key, callback));
    }

    function _buy(PoolKey memory key, CallbackData memory callback) private returns (uint256 amountOut) {
        BalanceDelta delta = poolManager.swap(
            key,
            IPoolManager.SwapParams({
                zeroForOne: true,
                amountSpecified: -callback.amountIn.toInt256(),
                sqrtPriceLimitX96: TickMath.MIN_SQRT_PRICE + 1
            }),
            callback.hookData
        );

        uint256 nativeDebt = uint256(uint128(-delta.amount0()));
        amountOut = uint256(uint128(delta.amount1()));
        if (nativeDebt != callback.amountIn) revert PartialFill();
        if (amountOut < callback.amountOutMinimum) {
            revert SlippageExceeded(amountOut, callback.amountOutMinimum);
        }

        // PoolManager's synced-currency slot is transient and shared for the whole
        // transaction. Clear any ERC-20 selected by an earlier batched action so
        // this native settlement cannot be forced down the ERC-20 branch.
        poolManager.sync(CurrencyLibrary.ADDRESS_ZERO);
        poolManager.settle{value: nativeDebt}();
        poolManager.take(key.currency1, callback.recipient, amountOut);
    }

    function _sell(PoolKey memory key, CallbackData memory callback) private returns (uint256 amountOut) {
        BalanceDelta delta = poolManager.swap(
            key,
            IPoolManager.SwapParams({
                zeroForOne: false,
                amountSpecified: -callback.amountIn.toInt256(),
                sqrtPriceLimitX96: TickMath.MAX_SQRT_PRICE - 1
            }),
            callback.hookData
        );

        uint256 tokenDebt = uint256(uint128(-delta.amount1()));
        amountOut = uint256(uint128(delta.amount0()));
        if (tokenDebt != callback.amountIn) revert PartialFill();
        if (amountOut < callback.amountOutMinimum) {
            revert SlippageExceeded(amountOut, callback.amountOutMinimum);
        }

        poolManager.sync(key.currency1);
        IERC20(callback.token).safeTransfer(address(poolManager), tokenDebt);
        poolManager.settle();
        poolManager.take(CurrencyLibrary.ADDRESS_ZERO, callback.recipient, amountOut);
    }

    receive() external payable {
        if (msg.sender != address(poolManager)) revert InvalidEthSender();
    }
}

src/CtrlNativeLaunchHook.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {IPoolManager} from "@uniswap/v4-core/src/interfaces/IPoolManager.sol";
import {IHooks} from "@uniswap/v4-core/src/interfaces/IHooks.sol";
import {Hooks} from "@uniswap/v4-core/src/libraries/Hooks.sol";
import {FullMath} from "@uniswap/v4-core/src/libraries/FullMath.sol";
import {SafeCast} from "@uniswap/v4-core/src/libraries/SafeCast.sol";
import {TickMath} from "@uniswap/v4-core/src/libraries/TickMath.sol";
import {BalanceDelta, BalanceDeltaLibrary} from "@uniswap/v4-core/src/types/BalanceDelta.sol";
import {
    BeforeSwapDelta,
    BeforeSwapDeltaLibrary,
    toBeforeSwapDelta
} from "@uniswap/v4-core/src/types/BeforeSwapDelta.sol";
import {Currency, CurrencyLibrary} from "@uniswap/v4-core/src/types/Currency.sol";
import {PoolId, PoolIdLibrary} from "@uniswap/v4-core/src/types/PoolId.sol";
import {PoolKey} from "@uniswap/v4-core/src/types/PoolKey.sol";
import {ICtrlFeeVault, ICtrlReferralRegistry} from "./interfaces/ICtrlProtocol.sol";

/// @notice Immutable native-currency Ctrl hook with deployment-time economics.
/// @dev The hook charges a 1% custom-accounting fee exclusively in the chain native currency (18 decimals).
contract CtrlNativeLaunchHook is IHooks {
    using BalanceDeltaLibrary for BalanceDelta;
    using PoolIdLibrary for PoolKey;
    using SafeCast for uint256;

    uint256 public constant BPS = 10_000;
    uint256 public constant TRADING_FEE_BPS = 100;
    uint256 public constant CREATOR_SHARE_BPS = 8_000;
    uint256 public constant REFERRAL_SHARE_BPS = 500;
    uint256 public constant BOUNTY_SHARE_BPS = 250;
    uint256 public immutable GRADUATION_THRESHOLD;

    uint24 public constant LP_FEE = 0;
    int24 public constant TICK_SPACING = 200;
    int24 public immutable INITIAL_TICK;
    int24 public constant TICK_LOWER = -887_200;
    int24 public immutable TICK_UPPER;
    bytes32 public constant SEED_HOOK_DATA = keccak256("CTRL_INITIAL_LIQUIDITY_V1");

    struct LaunchState {
        address token;
        address creator;
        address creatorPayout;
        uint256 netEthPrincipal;
        uint256 bountyAccrued;
        uint64 graduatedAt;
        bool seeded;
        bool graduated;
        bool exists;
    }

    struct SwapContext {
        address beneficiary;
        address referrer;
    }

    error AlreadyInitialized();
    error CallbackNotEnabled();
    error InitialLiquidityAlreadySeeded();
    error InvalidInitialLiquidity();
    error InvalidPool();
    error InvalidSwapDelta();
    error NotCreator();
    error NotFactory();
    error NotInitializer();
    error NotPoolManager();
    error PartialFill();
    error TokenAlreadyRegistered();
    error TokenNotRegistered();
    error ZeroAddress();

    event FactoryInitialized(address indexed factory);
    event LaunchRegistered(
        address indexed token, PoolId indexed poolId, address indexed creator, address creatorPayout
    );
    event InitialLiquiditySeeded(address indexed token, PoolId indexed poolId, int256 liquidityDelta);
    event CreatorPayoutUpdated(address indexed token, address indexed previousPayout, address indexed newPayout);
    event FeeAccrued(
        address indexed token,
        PoolId indexed poolId,
        address indexed beneficiary,
        address referrer,
        address referralPayout,
        uint256 feeAmount,
        uint256 creatorAmount,
        uint256 referralAmount,
        uint256 protocolAmount,
        uint256 bountyAmount
    );
    event PrincipalUpdated(
        address indexed token, PoolId indexed poolId, uint256 previousPrincipal, uint256 newPrincipal
    );
    event TokenGraduated(
        address indexed token,
        PoolId indexed poolId,
        address indexed beneficiary,
        uint256 principal,
        uint256 bounty,
        uint64 graduatedAt
    );

    IPoolManager public immutable poolManager;
    address public immutable positionManager;
    ICtrlFeeVault public immutable feeVault;
    ICtrlReferralRegistry public immutable referralRegistry;
    address public immutable initializer;
    address public factory;

    mapping(PoolId poolId => LaunchState launch) private _launches;
    mapping(address token => PoolId poolId) public poolIdForToken;

    constructor(
        address poolManager_,
        address positionManager_,
        address feeVault_,
        address referralRegistry_,
        address initializer_,
        uint256 graduationThreshold_,
        int24 initialTick_
    ) {
        require(graduationThreshold_ > 0, "zero graduation threshold");
        require(
            initialTick_ > TICK_LOWER && initialTick_ <= 887_200 && initialTick_ % TICK_SPACING == 0,
            "invalid initial tick"
        );
        GRADUATION_THRESHOLD = graduationThreshold_;
        INITIAL_TICK = initialTick_;
        TICK_UPPER = initialTick_;
        if (
            poolManager_ == address(0) || positionManager_ == address(0) || feeVault_ == address(0)
                || referralRegistry_ == address(0) || initializer_ == address(0)
        ) {
            revert ZeroAddress();
        }
        poolManager = IPoolManager(poolManager_);
        positionManager = positionManager_;
        feeVault = ICtrlFeeVault(feeVault_);
        referralRegistry = ICtrlReferralRegistry(referralRegistry_);
        initializer = initializer_;

        Hooks.validateHookPermissions(IHooks(address(this)), getHookPermissions());
    }

    modifier onlyPoolManager() {
        if (msg.sender != address(poolManager)) revert NotPoolManager();
        _;
    }

    modifier onlyFactory() {
        if (msg.sender != factory) revert NotFactory();
        _;
    }

    function initializeFactory(address factory_) external {
        if (msg.sender != initializer) revert NotInitializer();
        if (factory != address(0)) revert AlreadyInitialized();
        if (factory_ == address(0)) revert ZeroAddress();
        factory = factory_;
        emit FactoryInitialized(factory_);
    }

    function getHookPermissions() public pure returns (Hooks.Permissions memory permissions) {
        permissions.beforeInitialize = true;
        permissions.beforeAddLiquidity = true;
        permissions.beforeSwap = true;
        permissions.afterSwap = true;
        permissions.beforeSwapReturnDelta = true;
        permissions.afterSwapReturnDelta = true;
    }

    function poolKey(address token) public view returns (PoolKey memory key) {
        key = PoolKey({
            currency0: CurrencyLibrary.ADDRESS_ZERO,
            currency1: Currency.wrap(token),
            fee: LP_FEE,
            tickSpacing: TICK_SPACING,
            hooks: IHooks(address(this))
        });
    }

    function registerLaunch(address token, address creator, address creatorPayout)
        external
        onlyFactory
        returns (PoolId poolId)
    {
        if (token == address(0) || creator == address(0) || creatorPayout == address(0)) {
            revert ZeroAddress();
        }
        if (PoolId.unwrap(poolIdForToken[token]) != bytes32(0)) revert TokenAlreadyRegistered();

        PoolKey memory key = poolKey(token);
        poolId = key.toId();
        if (_launches[poolId].exists) revert TokenAlreadyRegistered();

        _launches[poolId] = LaunchState({
            token: token,
            creator: creator,
            creatorPayout: creatorPayout,
            netEthPrincipal: 0,
            bountyAccrued: 0,
            graduatedAt: 0,
            seeded: false,
            graduated: false,
            exists: true
        });
        poolIdForToken[token] = poolId;
        emit LaunchRegistered(token, poolId, creator, creatorPayout);
    }

    function updateCreatorPayout(address token, address newPayout) external onlyFactory {
        if (newPayout == address(0)) revert ZeroAddress();
        LaunchState storage launch = _launchForToken(token);
        address previousPayout = launch.creatorPayout;
        launch.creatorPayout = newPayout;
        emit CreatorPayoutUpdated(token, previousPayout, newPayout);
    }

    function getLaunch(address token) external view returns (LaunchState memory) {
        return _launchForToken(token);
    }

    function getLaunchByPoolId(PoolId poolId) external view returns (LaunchState memory) {
        LaunchState memory launch = _launches[poolId];
        if (!launch.exists) revert TokenNotRegistered();
        return launch;
    }

    function beforeInitialize(address sender, PoolKey calldata key, uint160 sqrtPriceX96)
        external
        view
        onlyPoolManager
        returns (bytes4)
    {
        LaunchState storage launch = _validatedLaunch(key);
        if (sender != factory || sqrtPriceX96 != TickMath.getSqrtPriceAtTick(INITIAL_TICK)) revert InvalidPool();
        if (launch.seeded) revert InvalidPool();
        return IHooks.beforeInitialize.selector;
    }

    function beforeAddLiquidity(
        address sender,
        PoolKey calldata key,
        IPoolManager.ModifyLiquidityParams calldata params,
        bytes calldata hookData
    ) external onlyPoolManager returns (bytes4) {
        LaunchState storage launch = _validatedLaunch(key);
        if (launch.seeded) revert InitialLiquidityAlreadySeeded();
        if (
            sender != positionManager || params.tickLower != TICK_LOWER || params.tickUpper != TICK_UPPER
                || params.liquidityDelta <= 0 || hookData.length != 32
                || keccak256(hookData) != keccak256(abi.encodePacked(SEED_HOOK_DATA))
        ) {
            revert InvalidInitialLiquidity();
        }

        launch.seeded = true;
        emit InitialLiquiditySeeded(launch.token, key.toId(), params.liquidityDelta);
        return IHooks.beforeAddLiquidity.selector;
    }

    function beforeSwap(address, PoolKey calldata key, IPoolManager.SwapParams calldata params, bytes calldata hookData)
        external
        onlyPoolManager
        returns (bytes4, BeforeSwapDelta, uint24)
    {
        LaunchState storage launch = _validatedLaunch(key);
        if (!launch.seeded) revert InvalidPool();

        bool exactInput = params.amountSpecified < 0;
        bool nativeSpecified = exactInput == params.zeroForOne;
        uint256 feeAmount;

        if (nativeSpecified) {
            uint256 nativeAmount = _absoluteAmount(params.amountSpecified);
            feeAmount = exactInput ? _feeFromGross(nativeAmount) : _feeOnTop(nativeAmount);
            _mintAndAccrue(key.toId(), launch, feeAmount, hookData);
        }

        return (
            IHooks.beforeSwap.selector,
            feeAmount == 0 ? BeforeSwapDeltaLibrary.ZERO_DELTA : toBeforeSwapDelta(feeAmount.toInt128(), 0),
            0
        );
    }

    function afterSwap(
        address,
        PoolKey calldata key,
        IPoolManager.SwapParams calldata params,
        BalanceDelta delta,
        bytes calldata hookData
    ) external onlyPoolManager returns (bytes4, int128) {
        PoolId poolId = key.toId();
        LaunchState storage launch = _validatedLaunch(key);
        bool exactInput = params.amountSpecified < 0;
        bool buy = params.zeroForOne;
        bool nativeSpecified = exactInput == params.zeroForOne;
        int128 nativeDelta = delta.amount0();
        uint256 feeAmount;
        if ((buy && nativeDelta >= 0) || (!buy && nativeDelta <= 0)) revert InvalidSwapDelta();

        if (nativeSpecified) {
            uint256 requestedNative = _absoluteAmount(params.amountSpecified);
            feeAmount = exactInput ? _feeFromGross(requestedNative) : _feeOnTop(requestedNative);
            uint256 expectedPoolNative = exactInput ? requestedNative - feeAmount : requestedNative + feeAmount;
            if (_absoluteAmount(nativeDelta) != expectedPoolNative) revert PartialFill();
        } else {
            uint256 actualPoolNative = _absoluteAmount(nativeDelta);
            feeAmount = buy ? _feeOnTop(actualPoolNative) : _feeFromGross(actualPoolNative);
            _mintAndAccrue(poolId, launch, feeAmount, hookData);
        }

        _updatePrincipalAndGraduate(poolId, launch, buy, _absoluteAmount(nativeDelta), hookData);
        return (IHooks.afterSwap.selector, nativeSpecified ? int128(0) : feeAmount.toInt128());
    }

    function afterInitialize(address, PoolKey calldata, uint160, int24) external pure returns (bytes4) {
        revert CallbackNotEnabled();
    }

    function afterAddLiquidity(
        address,
        PoolKey calldata,
        IPoolManager.ModifyLiquidityParams calldata,
        BalanceDelta,
        BalanceDelta,
        bytes calldata
    ) external pure returns (bytes4, BalanceDelta) {
        revert CallbackNotEnabled();
    }

    function beforeRemoveLiquidity(
        address,
        PoolKey calldata,
        IPoolManager.ModifyLiquidityParams calldata,
        bytes calldata
    ) external pure returns (bytes4) {
        revert CallbackNotEnabled();
    }

    function afterRemoveLiquidity(
        address,
        PoolKey calldata,
        IPoolManager.ModifyLiquidityParams calldata,
        BalanceDelta,
        BalanceDelta,
        bytes calldata
    ) external pure returns (bytes4, BalanceDelta) {
        revert CallbackNotEnabled();
    }

    function beforeDonate(address, PoolKey calldata, uint256, uint256, bytes calldata) external pure returns (bytes4) {
        revert CallbackNotEnabled();
    }

    function afterDonate(address, PoolKey calldata, uint256, uint256, bytes calldata) external pure returns (bytes4) {
        revert CallbackNotEnabled();
    }

    function _mintAndAccrue(PoolId poolId, LaunchState storage launch, uint256 feeAmount, bytes calldata hookData)
        private
    {
        if (feeAmount == 0) return;

        SwapContext memory context = _parseContext(hookData);
        address referralPayout =
            context.referrer == address(0) ? address(0) : referralRegistry.payoutOf(context.referrer);
        uint256 creatorAmount = FullMath.mulDiv(feeAmount, CREATOR_SHARE_BPS, BPS);
        uint256 referralAmount = referralPayout == address(0) ? 0 : FullMath.mulDiv(feeAmount, REFERRAL_SHARE_BPS, BPS);
        uint256 bountyAmount = launch.graduated ? 0 : FullMath.mulDiv(feeAmount, BOUNTY_SHARE_BPS, BPS);
        uint256 protocolAmount = feeAmount - creatorAmount - referralAmount - bountyAmount;

        poolManager.mint(address(feeVault), 0, feeAmount);
        feeVault.accrue(
            launch.token,
            launch.creatorPayout,
            creatorAmount,
            referralPayout,
            referralAmount,
            protocolAmount,
            bountyAmount
        );
        launch.bountyAccrued += bountyAmount;

        emit FeeAccrued(
            launch.token,
            poolId,
            context.beneficiary,
            context.referrer,
            referralPayout,
            feeAmount,
            creatorAmount,
            referralAmount,
            protocolAmount,
            bountyAmount
        );
    }

    function _updatePrincipalAndGraduate(
        PoolId poolId,
        LaunchState storage launch,
        bool buy,
        uint256 poolNativeAmount,
        bytes calldata hookData
    ) private {
        uint256 previousPrincipal = launch.netEthPrincipal;
        uint256 newPrincipal;

        if (buy) {
            newPrincipal = previousPrincipal + poolNativeAmount;
        } else {
            newPrincipal = poolNativeAmount >= previousPrincipal ? 0 : previousPrincipal - poolNativeAmount;
        }
        launch.netEthPrincipal = newPrincipal;
        emit PrincipalUpdated(launch.token, poolId, previousPrincipal, newPrincipal);

        if (!launch.graduated && previousPrincipal < GRADUATION_THRESHOLD && newPrincipal >= GRADUATION_THRESHOLD) {
            SwapContext memory context = _parseContext(hookData);
            address beneficiary = context.beneficiary;
            if (beneficiary == address(0)) beneficiary = feeVault.treasury();

            uint256 bounty = launch.bountyAccrued;
            launch.bountyAccrued = 0;
            launch.graduated = true;
            launch.graduatedAt = uint64(block.timestamp);
            if (bounty != 0) feeVault.releaseBounty(launch.token, beneficiary, bounty);

            emit TokenGraduated(launch.token, poolId, beneficiary, newPrincipal, bounty, launch.graduatedAt);
        }
    }

    function _validatedLaunch(PoolKey calldata key) private view returns (LaunchState storage launch) {
        if (
            !key.currency0.isAddressZero() || key.fee != LP_FEE || key.tickSpacing != TICK_SPACING
                || address(key.hooks) != address(this)
        ) {
            revert InvalidPool();
        }
        PoolId poolId = key.toId();
        launch = _launches[poolId];
        if (!launch.exists || Currency.unwrap(key.currency1) != launch.token) revert InvalidPool();
    }

    function _launchForToken(address token) private view returns (LaunchState storage launch) {
        PoolId poolId = poolIdForToken[token];
        launch = _launches[poolId];
        if (!launch.exists) revert TokenNotRegistered();
    }

    function _parseContext(bytes calldata hookData) private pure returns (SwapContext memory context) {
        if (hookData.length != 64) return context;

        uint256 beneficiaryWord;
        uint256 referrerWord;
        assembly ("memory-safe") {
            beneficiaryWord := calldataload(hookData.offset)
            referrerWord := calldataload(add(hookData.offset, 0x20))
        }
        if (beneficiaryWord >> 160 != 0 || referrerWord >> 160 != 0) return context;
        context.beneficiary = address(uint160(beneficiaryWord));
        context.referrer = address(uint160(referrerWord));
    }

    function _feeFromGross(uint256 gross) private pure returns (uint256) {
        return FullMath.mulDiv(gross, TRADING_FEE_BPS, BPS);
    }

    function _feeOnTop(uint256 net) private pure returns (uint256) {
        uint256 gross = FullMath.mulDivRoundingUp(net, BPS, BPS - TRADING_FEE_BPS);
        return gross - net;
    }

    function _absoluteAmount(int256 amount) private pure returns (uint256) {
        return amount < 0 ? uint256(-amount) : uint256(amount);
    }
}

src/CtrlNativeV4Factory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IPoolManager} from "@uniswap/v4-core/src/interfaces/IPoolManager.sol";
import {TickMath} from "@uniswap/v4-core/src/libraries/TickMath.sol";
import {Currency} from "@uniswap/v4-core/src/types/Currency.sol";
import {PoolId} from "@uniswap/v4-core/src/types/PoolId.sol";
import {PoolKey} from "@uniswap/v4-core/src/types/PoolKey.sol";
import {CtrlToken} from "./CtrlToken.sol";
import {CtrlLiquidityAmounts} from "./libraries/CtrlLiquidityAmounts.sol";
import {
    ICtrlFeeVault,
    ICtrlLaunchHook,
    ICtrlLaunchRouter,
    ICtrlPositionLocker,
    IPermit2Allowance,
    IPositionManagerMinimal
} from "./interfaces/ICtrlProtocol.sol";

/// @notice Permissionless, fixed-configuration Ctrl token factory.
contract CtrlNativeV4Factory is Ownable2Step, ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint256 public constant TOKEN_SUPPLY = 1_000_000_000 ether;
    uint256 public immutable LAUNCH_FEE;
    int24 public immutable INITIAL_TICK;
    int24 public constant TICK_SPACING = 200;
    int24 public constant TICK_LOWER = -887_200;
    int24 public immutable TICK_UPPER;

    uint256 public constant MAX_URI_LENGTH = 2_048;
    uint256 public constant MAX_DESCRIPTION_LENGTH = 4_096;
    uint256 public constant MAX_SOCIAL_LENGTH = 512;

    uint256 private constant ACTION_MINT_POSITION = 0x02;
    uint256 private constant ACTION_CLOSE_CURRENCY = 0x12;

    struct TokenParams {
        string name;
        string symbol;
        string metadataURI;
        string logoURI;
        string description;
        string website;
        string x;
        string telegram;
        string discord;
        string farcaster;
        address creatorPayout;
        address initialBuyRecipient;
        address initialBuyReferrer;
    }

    struct LaunchRecord {
        address token;
        address creator;
        address creatorPayout;
        PoolId poolId;
        uint256 positionId;
        uint256 supply;
        bool exists;
    }

    error DeadlineExpired();
    error ExternalContractMissing(address target);
    error InitialBuyNeedsSlippage();
    error InsufficientLaunchFee();
    error InvalidMetadata();
    error InvalidPool();
    error InvalidPosition();
    error LaunchesPaused();
    error NotCreator();
    error TokenDeploymentFailed();
    error TokenNotFound();
    error TreasuryTransferFailed();
    error ZeroAddress();

    event TokenLaunched(
        address indexed token,
        address indexed creator,
        PoolId indexed poolId,
        uint256 positionId,
        address creatorPayout,
        uint256 launchFeePaid,
        uint256 initialBuyEth,
        uint256 initialBuyTokens,
        address initialBuyRecipient,
        address initialBuyReferrer,
        bytes32 userSalt
    );
    event CreatorPayoutUpdated(address indexed token, address indexed previousPayout, address indexed newPayout);
    event LaunchPauseUpdated(bool paused);

    IPoolManager public immutable poolManager;
    IPositionManagerMinimal public immutable positionManager;
    IPermit2Allowance public immutable permit2;
    ICtrlPositionLocker public immutable locker;
    ICtrlLaunchHook public immutable hook;
    ICtrlLaunchRouter public immutable launchRouter;
    ICtrlFeeVault public immutable feeVault;

    /// @notice New deployments fail closed until the configured owner explicitly opens launches.
    bool public launchesArePaused = true;
    uint256 public totalLaunches;

    mapping(address token => LaunchRecord record) private _launches;

    constructor(
        address initialOwner,
        address poolManager_,
        address positionManager_,
        address permit2_,
        address locker_,
        address hook_,
        address launchRouter_,
        address feeVault_,
        uint256 launchFee_,
        int24 initialTick_
    ) Ownable(initialOwner) {
        require(launchFee_ > 0, "zero launch fee");
        require(
            initialTick_ > TICK_LOWER && initialTick_ <= 887_200 && initialTick_ % TICK_SPACING == 0,
            "invalid initial tick"
        );
        require(ICtrlNativeEconomics(hook_).INITIAL_TICK() == initialTick_, "hook tick mismatch");
        LAUNCH_FEE = launchFee_;
        INITIAL_TICK = initialTick_;
        TICK_UPPER = initialTick_;
        if (
            initialOwner == address(0) || poolManager_ == address(0) || positionManager_ == address(0)
                || permit2_ == address(0) || locker_ == address(0) || hook_ == address(0) || launchRouter_ == address(0)
                || feeVault_ == address(0)
        ) {
            revert ZeroAddress();
        }
        _requireCode(poolManager_);
        _requireCode(positionManager_);
        _requireCode(permit2_);
        _requireCode(locker_);
        _requireCode(hook_);
        _requireCode(launchRouter_);
        _requireCode(feeVault_);

        poolManager = IPoolManager(poolManager_);
        positionManager = IPositionManagerMinimal(positionManager_);
        permit2 = IPermit2Allowance(permit2_);
        locker = ICtrlPositionLocker(locker_);
        hook = ICtrlLaunchHook(hook_);
        launchRouter = ICtrlLaunchRouter(launchRouter_);
        feeVault = ICtrlFeeVault(feeVault_);
    }

    function initialSqrtPriceX96() external view returns (uint160) {
        return TickMath.getSqrtPriceAtTick(INITIAL_TICK);
    }

    function launchToken(TokenParams calldata params, bytes32 userSalt, uint256 initialBuyMinimum, uint256 deadline)
        external
        payable
        nonReentrant
        returns (address token, PoolId poolId, uint256 positionId, uint256 initialBuyTokens)
    {
        if (launchesArePaused) revert LaunchesPaused();
        if (msg.value < LAUNCH_FEE) revert InsufficientLaunchFee();
        _validateTokenParams(params);

        uint256 initialBuyEth = msg.value - LAUNCH_FEE;
        if (initialBuyEth != 0) {
            if (initialBuyMinimum == 0) revert InitialBuyNeedsSlippage();
            if (deadline < block.timestamp) revert DeadlineExpired();
        }

        address creatorPayout = params.creatorPayout == address(0) ? msg.sender : params.creatorPayout;
        bytes32 derivedSalt = keccak256(abi.encode(msg.sender, userSalt));
        bytes memory creationCode = _tokenCreationCode(params, msg.sender);
        token = _deployToken(derivedSalt, creationCode);

        poolId = hook.registerLaunch(token, msg.sender, creatorPayout);
        PoolKey memory key = hook.poolKey(token);
        _validatePool(token, key, poolId);
        CtrlToken(token).setPoolId(PoolId.unwrap(poolId));
        poolManager.initialize(key, TickMath.getSqrtPriceAtTick(INITIAL_TICK));

        positionId = _mintAndLockPosition(token, key, poolId);
        _launches[token] = LaunchRecord({
            token: token,
            creator: msg.sender,
            creatorPayout: creatorPayout,
            poolId: poolId,
            positionId: positionId,
            supply: TOKEN_SUPPLY,
            exists: true
        });
        totalLaunches++;

        _payLaunchFee();

        address initialBuyRecipient;
        if (initialBuyEth != 0) {
            initialBuyRecipient = params.initialBuyRecipient == address(0) ? msg.sender : params.initialBuyRecipient;
            initialBuyTokens = launchRouter.buyExactIn{value: initialBuyEth}(
                token, initialBuyRecipient, msg.sender, params.initialBuyReferrer, initialBuyMinimum, deadline
            );
        }

        emit TokenLaunched(
            token,
            msg.sender,
            poolId,
            positionId,
            creatorPayout,
            LAUNCH_FEE,
            initialBuyEth,
            initialBuyTokens,
            initialBuyRecipient,
            params.initialBuyReferrer,
            userSalt
        );
    }

    function predictTokenAddress(TokenParams calldata params, bytes32 userSalt, address creator)
        external
        view
        returns (address)
    {
        if (creator == address(0)) revert ZeroAddress();
        bytes32 derivedSalt = keccak256(abi.encode(creator, userSalt));
        return _computeCreate2Address(derivedSalt, keccak256(_tokenCreationCode(params, creator)));
    }

    function setCreatorPayout(address token, address newPayout) external {
        if (newPayout == address(0)) revert ZeroAddress();
        LaunchRecord storage launched = _launches[token];
        if (!launched.exists) revert TokenNotFound();
        if (launched.creator != msg.sender) revert NotCreator();

        address previousPayout = launched.creatorPayout;
        launched.creatorPayout = newPayout;
        hook.updateCreatorPayout(token, newPayout);
        emit CreatorPayoutUpdated(token, previousPayout, newPayout);
    }

    function setLaunchesPaused(bool paused) external onlyOwner {
        launchesArePaused = paused;
        emit LaunchPauseUpdated(paused);
    }

    function getLaunch(address token) external view returns (LaunchRecord memory) {
        return _launches[token];
    }

    function _mintAndLockPosition(address token, PoolKey memory key, PoolId poolId)
        private
        returns (uint256 positionId)
    {
        uint160 sqrtLower = TickMath.getSqrtPriceAtTick(TICK_LOWER);
        uint160 sqrtUpper = TickMath.getSqrtPriceAtTick(TICK_UPPER);
        uint128 liquidity = CtrlLiquidityAmounts.getLiquidityForAmount1(sqrtLower, sqrtUpper, TOKEN_SUPPLY);
        if (liquidity == 0) revert InvalidPosition();

        positionId = positionManager.nextTokenId();
        IERC20(token).forceApprove(address(permit2), TOKEN_SUPPLY);
        permit2.approve(token, address(positionManager), uint160(TOKEN_SUPPLY), uint48(block.timestamp + 1));

        bytes memory actions = abi.encodePacked(
            bytes1(uint8(ACTION_MINT_POSITION)),
            bytes1(uint8(ACTION_CLOSE_CURRENCY)),
            bytes1(uint8(ACTION_CLOSE_CURRENCY))
        );
        bytes[] memory actionParams = new bytes[](3);
        actionParams[0] = abi.encode(
            key,
            TICK_LOWER,
            TICK_UPPER,
            uint256(liquidity),
            uint128(0),
            uint128(TOKEN_SUPPLY),
            address(locker),
            abi.encodePacked(hook.SEED_HOOK_DATA())
        );
        actionParams[1] = abi.encode(key.currency0);
        actionParams[2] = abi.encode(key.currency1);
        positionManager.modifyLiquidities(abi.encode(actions, actionParams), block.timestamp);

        permit2.approve(token, address(positionManager), 0, 0);
        IERC20(token).forceApprove(address(permit2), 0);
        if (positionManager.ownerOf(positionId) != address(locker)) revert InvalidPosition();
        if (positionManager.getPositionLiquidity(positionId) != liquidity) revert InvalidPosition();

        uint256 dust = IERC20(token).balanceOf(address(this));
        if (dust != 0) {
            IERC20(token).safeTransfer(address(locker), dust);
            locker.noteTokenDust(token, dust);
        }
        locker.registerPosition(token, poolId, positionId);
    }

    function _validatePool(address token, PoolKey memory key, PoolId poolId) private view {
        if (
            !key.currency0.isAddressZero() || Currency.unwrap(key.currency1) != token || key.fee != 0
                || key.tickSpacing != TICK_SPACING || address(key.hooks) != address(hook)
                || PoolId.unwrap(key.toId()) != PoolId.unwrap(poolId)
                || PoolId.unwrap(hook.poolIdForToken(token)) != PoolId.unwrap(poolId)
        ) {
            revert InvalidPool();
        }
    }

    function _payLaunchFee() private {
        (bool sent,) = payable(feeVault.treasury()).call{value: LAUNCH_FEE}("");
        if (!sent) revert TreasuryTransferFailed();
    }

    function _tokenCreationCode(TokenParams calldata params, address creator) private pure returns (bytes memory) {
        return abi.encodePacked(
            type(CtrlToken).creationCode,
            abi.encode(
                params.name,
                params.symbol,
                params.metadataURI,
                params.logoURI,
                params.description,
                params.website,
                params.x,
                params.telegram,
                params.discord,
                params.farcaster,
                creator,
                TOKEN_SUPPLY
            )
        );
    }

    function _deployToken(bytes32 salt, bytes memory creationCode) private returns (address token) {
        assembly ("memory-safe") {
            token := create2(0, add(creationCode, 0x20), mload(creationCode), salt)
        }
        if (token == address(0)) revert TokenDeploymentFailed();
    }

    function _computeCreate2Address(bytes32 salt, bytes32 initCodeHash) private view returns (address) {
        return address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xff), address(this), salt, initCodeHash)))));
    }

    function _validateTokenParams(TokenParams calldata params) private pure {
        uint256 nameLength = bytes(params.name).length;
        uint256 symbolLength = bytes(params.symbol).length;
        if (
            nameLength == 0 || nameLength > 64 || symbolLength == 0 || symbolLength > 32
                || bytes(params.metadataURI).length > MAX_URI_LENGTH || bytes(params.logoURI).length > MAX_URI_LENGTH
                || bytes(params.description).length > MAX_DESCRIPTION_LENGTH
                || bytes(params.website).length > MAX_SOCIAL_LENGTH || bytes(params.x).length > MAX_SOCIAL_LENGTH
                || bytes(params.telegram).length > MAX_SOCIAL_LENGTH || bytes(params.discord).length > MAX_SOCIAL_LENGTH
                || bytes(params.farcaster).length > MAX_SOCIAL_LENGTH
        ) {
            revert InvalidMetadata();
        }
    }

    function _requireCode(address target) private view {
        if (target.code.length == 0) revert ExternalContractMissing(target);
    }
}

interface ICtrlNativeEconomics {
    function INITIAL_TICK() external view returns (int24);
}

